	namespace App\Adminx\Support;

	defined('BASEPATH') || die('Direct access to this location is not allowed.');

	/** Contextual help shown on Adminx section pages. */
	class SectionHelp
	{
		public static function forPath($path)
		{
			$path = '/' . trim((string) $path, '/');
			$moduleHelp = self::moduleDefinition($path);
			if ($moduleHelp !== null) {
				return $moduleHelp;
			}

			foreach (self::definitions() as $definition) {
				if (preg_match($definition['pattern'], $path)) {
					unset($definition['pattern']);
					return $definition;
				}
			}

			return null;
		}

		protected static function moduleDefinition($path)
		{
			foreach (\App\Common\ModuleManager::all() as $module) {
				$extension = isset($module['admin_extension']) && is_array($module['admin_extension']) ? $module['admin_extension'] : array();
				$url = isset($extension['url']) ? '/' . trim((string) $extension['url'], '/') : '';
				$help = isset($extension['help']) && is_array($extension['help']) ? $extension['help'] : array();
				if ($url === '' || !$help || ($path !== $url && strpos($path, $url . '/') !== 0)) {
					continue;
				}

				$title = trim(isset($help['title']) ? (string) $help['title'] : (isset($module['name']) ? (string) $module['name'] : ''));
				$description = trim(isset($help['description']) ? (string) $help['description'] : '');
				$items = array();
				foreach (isset($help['items']) && is_array($help['items']) ? $help['items'] : array() as $item) {
					$item = trim((string) $item);
					if ($item !== '') {
						$items[] = $item;
					}
				}

				if ($title === '' || $description === '' || !$items) {
					return null;
				}

				return array(
					'title' => AdminLocale::translateMarkup($title),
					'description' => AdminLocale::translateMarkup($description),
					'items' => array_map(array(AdminLocale::class, 'translateMarkup'), $items),
					'note' => AdminLocale::translateMarkup(trim(isset($help['note']) ? (string) $help['note'] : '')),
					'doc' => trim(isset($help['doc']) ? (string) $help['doc'] : ''),
				);
			}

			return null;
		}

